package app;import api.*;import java.util.*;public class Main{public static void main(String[]a){GameData d=new GameData();ServiceLoader.load(IGamePluginService.class).forEach(p->{System.out.println("Loaded plugin: "+p.name());p.start(d);});ServiceLoader.load(IEntityProcessingService.class).forEach(p->p.process(d,1));d.entities.forEach(e->System.out.println(e.type+" x="+e.x));}}